def sentence_asymmetry_divergence(text, anchor):
    if not text:
        return 0.5
    sentences = re.split(r'[.!?\n]+', text)
    sentences = [s.strip() for s in sentences if s.strip()]
    if len(sentences) < 2:
        return 0.5
    sent_means = []
    for sent in sentences:
        content = _content(sent)
        if content:
            surps = [_word_surprisal(w) for w in content]
            sent_means.append(statistics.mean(surps))
        else:
            sent_means.append(5.0)
    if len(sent_means) < 2:
        return 0.5
    sent_array = np.array(sent_means)
    if sent_array.std() < 0.1:
        asymmetry = 0.0
    else:
        asymmetry = sent_array.std() / (sent_array.mean() + 0.1)
    return min(1.0, max(0.0, asymmetry / 3.0))

METRICS = {"sentence_asymmetry_divergence": sentence_asymmetry_divergence}
